//! Independent ordinary rune altar World actions; pinned Wiki recipe facts, no developer tests invoked.
use gielinor_world::{simulation::{World,PlayerData,ActorId,Action,WorldEvent},runecrafting::{Config,Recipe},locations::Location,loc_collision::{self,LocCollision},inventory::Item,stats::Stats,npc::RandomSource,CoordGrid};
struct NoDraw;impl RandomSource for NoDraw{fn below(&mut self,_:u32)->u32{panic!("ordinary rune binding unexpectedly drew RNG")}}
const ROWS:[(u32,i32,u8,u16,u8);6]=[(34760,556,1,50,11),(34761,558,2,55,14),(34762,555,5,60,19),(34763,557,9,65,26),(34764,554,14,70,35),(34765,559,20,75,46)];
fn fixture(row:usize,member:bool,kind:usize,current:u8,count:usize,rate:i32)->(World,ActorId,Location,Vec<(usize,i32)>){let(id,output,level,xp,interval)=ROWS[row];let mut w=World::default();for x in [3216,3224]{for z in [3216,3224]{w.collision.allocate(x,z,0);}}let location=Location::new(CoordGrid::new(3221,3220,0).unwrap(),id,10,0).unwrap();let ty=LocCollision{width:3,length:3,block_walk:2,block_range:true,break_route_finding:false};w.location_types.insert(id,ty);w.locations.load(location);loc_collision::toggle(&mut w.collision,location.coords,location.shape,location.angle,ty,true).unwrap();w.runecrafting=Some(Config{altars:[(id,Recipe{output,level,xp_tenths:xp,interval,name:"independent rune"})].into(),blocked_held:[26879,28593,28595,28597,28599].into(),blocked_worn:[26850].into(),animation:791,spot:186});w.object_types.stackable.insert(output);let mut stats=Stats::default();stats.set_base(3,10);stats.set_current(3,10);stats.set_base(20,99);stats.set_current(20,current as i8);stats.set_fine_xp(20,130344311).unwrap();let mut d=PlayerData::new(1,"Independent rune binder".into(),CoordGrid::new(3220,3220,0).unwrap(),stats);d.xp_rate_hundreds=rate;for s in 0..28{d.inventory.restore_slot(s,Some(Item{id:if s==27{995}else{1931},count:if s==27{1000}else{1},vars:0})).unwrap();}let mut parts=vec![];for k in 0..count{let slot=(k*9+7)%28;let id=match kind{0=>1436,1=>7936,_=>if k%2==0{1436}else{7936}};d.inventory.restore_slot(slot,Some(Item{id,count:1,vars:0})).unwrap();parts.push((slot,id));}d.equipment.restore_slot(0,Some(Item{id:1155,count:1,vars:7})).unwrap();d.equipment.restore_slot(4,Some(Item{id:1129,count:1,vars:9})).unwrap();w.queue_login(1,d).unwrap();w.tick_with_random(&mut NoDraw).unwrap();let actor=w.actors().next().unwrap();w.set_membership(actor,member).unwrap();w.drain_events();(w,actor,location,parts)}
fn request(w:&mut World,a:ActorId,location:Location){assert!(w.has_location_handler(location.id,1));assert!(!w.has_location_handler(location.id,2));w.submit(a,Action::OperateLocation{coords:location.coords,id:location.id,operation:1,control:false}).unwrap();w.tick_with_random(&mut NoDraw).unwrap();}

fn special(w:&mut World,a:ActorId,parts:&[(usize,i32)]){for(slot,_)in parts{w.data_mut(a).unwrap().inventory.restore_slot(*slot,Some(Item{id:24704,count:1,vars:0})).unwrap();}}

#[test]fn one_hundred_forty_four_late_world_context_and_catalog_refusals(){use gielinor_world::inventory::{Template,StackType};let mut n=0;for row in 0..6{for case in 0..24{let(mut w,a,l,parts)=fixture(row,true,2,99,7,125);special(&mut w,a,&parts);request(&mut w,a,l);let slot=parts[0].0;let output=ROWS[row].1;match case{0=>w.data_mut(a).unwrap().inventory.restore_slot(slot,None).unwrap(),1=>w.data_mut(a).unwrap().inventory.restore_slot(slot,Some(Item{id:7936,count:1,vars:0})).unwrap(),2=>w.runecrafting=None,3=>w.runecrafting.as_mut().unwrap().altars.get_mut(&l.id).unwrap().xp_tenths+=1,4=>{w.locations.delete(l);},5=>{w.locations.delete(l);w.locations.load(l);},6=>{w.set_modal_open(a,true).unwrap();w.close_dialogs(a).unwrap();w.set_modal_open(a,false).unwrap();},7=>w.submit(a,Action::Walk{destination:CoordGrid::new(3220,3221,0).unwrap(),run:false}).unwrap(),8=>w.request_logout(a).unwrap(),9=>{w.object_types.dummy.insert(output);},10=>{w.object_types.stackable.remove(&output);},11=>{w.object_types.dummy.insert(24704);},12=>{w.object_types.stackable.insert(24704);},13=>{w.object_types.notes.insert(output,Template{link:output,template:799});},14=>{w.object_types.placeholders.insert(output,Template{link:output,template:14401});},15=>{w.object_types.transforms.insert(output,Template{link:output,template:1});},16=>{w.object_types.notes.insert(24704,Template{link:24704,template:799});},17=>{w.object_types.placeholders.insert(24704,Template{link:24704,template:14401});},18=>{w.object_types.transforms.insert(24704,Template{link:24704,template:1});},19=>{w.delay_player(a,8).unwrap();w.close_dialogs(a).unwrap();},20=>w.set_modal_open(a,true).unwrap(),21=>{w.runecrafting.as_mut().unwrap().altars.remove(&l.id);},22=>w.data_mut(a).unwrap().inventory.stack=StackType::Always,_=>w.data_mut(a).unwrap().inventory.placeholders=true}let before=w.data(a).unwrap().clone();for _ in 0..12{w.tick_with_random(&mut NoDraw).unwrap();}let d=w.data(a).unwrap();assert_eq!(d.inventory.slots(),before.inventory.slots(),"row{row} latecontext{case}");assert_eq!(d.inventory.stack,before.inventory.stack);assert_eq!(d.inventory.placeholders,before.inventory.placeholders);assert_eq!(d.equipment.slots(),before.equipment.slots());assert_eq!(d.stats,before.stats);n+=1;}}assert_eq!(n,144);println!("PG_DAEYALT_CONTEXT144 latecaptured/config/revision/close/move/logout/modal/catalog/templates/inventoryshape refusals;physicalwholeimages exclude legitimate save dirtyflagclear PASS");}
fn expected(w:&World,a:ActorId,row:usize,parts:&[(usize,i32)]) -> (gielinor_world::inventory::Inventory,Stats){let d=w.data(a).unwrap();let mut bag=d.inventory.clone();for(slot,_)in parts{bag.restore_slot(*slot,None).unwrap();}bag.restore_slot(parts.iter().map(|p|p.0).min().unwrap(),Some(Item{id:ROWS[row].1,count:7*(i32::from(99/ROWS[row].4)+1),vars:0})).unwrap();let mut stats=d.stats.clone();stats.set_fine_xp(20,130344311+7*i32::from(ROWS[row].3)*150*125/10000).unwrap();(bag,stats)}
#[test]fn twelve_new_uncaptured_essences_are_preserved(){for row in 0..6{for extra in[7936,24704]{let(mut w,a,l,parts)=fixture(row,true,2,99,7,125);special(&mut w,a,&parts);request(&mut w,a,l);assert!(!parts.iter().any(|p|p.0==0));w.data_mut(a).unwrap().inventory.restore_slot(0,Some(Item{id:extra,count:1,vars:0})).unwrap();let(bag,stats)=expected(&w,a,row,&parts);let gear=w.data(a).unwrap().equipment.clone();w.tick_with_random(&mut NoDraw).unwrap();assert_eq!(w.data(a).unwrap().inventory,bag);assert_eq!(w.data(a).unwrap().equipment,gear);assert_eq!(w.data(a).unwrap().stats,stats);}}println!("PG_DAEYALT_CONTEXT12 uncapturedadditionalPureorDaeyalt remains nextclick PASS");}
#[test]fn six_live_delay_parks_then_completes_once_without_cancellation(){for row in 0..6{let(mut w,a,l,parts)=fixture(row,true,2,99,7,125);special(&mut w,a,&parts);request(&mut w,a,l);w.delay_player(a,8).unwrap();let before=w.data(a).unwrap().clone();let(bag,stats)=expected(&w,a,row,&parts);for _ in 0..3{w.tick_with_random(&mut NoDraw).unwrap();assert!(w.protection(a).unwrap().delayed());assert_eq!(w.data(a).unwrap().inventory,before.inventory);assert_eq!(w.data(a).unwrap().stats,before.stats);}for _ in 0..10{w.tick_with_random(&mut NoDraw).unwrap();}assert_eq!(w.data(a).unwrap().inventory,bag);assert_eq!(w.data(a).unwrap().stats,stats);assert_eq!(w.data(a).unwrap().equipment,before.equipment);}println!("PG_DAEYALT_CONTEXT6 delayparks thenresumes once noRNG exactreward PASS");}
